function removeCodeFences(value) {
    return value
        .trim()
        .replace(/^```json\s*/i, "")
        .replace(/^```text\s*/i, "")
        .replace(/```$/i, "")
        .trim();
}

function getLlmOutput(message) {
    const candidates = [
        message.payload?.response,
        message.payload?.content,
        message.payload?.text,
        message.payload?.message?.content,
        message.payload?.choices?.[0]?.message?.content,
        message.response?.content,
        message.response?.text,
        message.response,
        message.result?.content,
        message.result,
        message.payload
    ];

    for (const value of candidates) {
        if (value !== undefined && value !== null) {
            return value;
        }
    }

    throw new Error("No LLM output found");
}

function validateClassification(data) {
    const sentiments = ["positive", "neutral", "negative"];
    const categories = ["cards", "loans", "app", "fraud", "other"];
    const urgency = Number(data.urgency);

    if (!sentiments.includes(data.sentiment)) {
        throw new Error("Invalid sentiment");
    }

    if (!categories.includes(data.category)) {
        throw new Error("Invalid category");
    }

    if (!Number.isInteger(urgency) || urgency < 1 || urgency > 5) {
        throw new Error("Invalid urgency");
    }

    if (
        typeof data.summary !== "string" ||
        !data.summary.trim() ||
        /[\r\n]/.test(data.summary)
    ) {
        throw new Error("Invalid one-line summary");
    }

    return {
        sentiment: data.sentiment,
        category: data.category,
        urgency: urgency,
        summary: data.summary.trim().slice(0, 300)
    };
}

try {
    const rawOutput = getLlmOutput(msg);

    const parsedOutput =
        typeof rawOutput === "string"
            ? JSON.parse(removeCodeFences(rawOutput))
            : rawOutput;

    msg.classification = validateClassification(parsedOutput);
    msg.classificationValid = true;
    msg.llmRetryCount = Number(msg.llmRetryCount || 0);
}
catch (error) {
    msg.classificationValid = false;
    msg.llmRetryCount = Number(msg.llmRetryCount || 0);
    msg.llmParseError = error.message;
}

return msg;

